70	  decision.resource_id = RouteLockId(from_station, to_station);
71	  const auto lock = route_locks.find(decision.resource_id);
72	  if (lock == route_locks.end()) {
73	    decision.message = "route resource not found: " + decision.resource_id;
74	    return decision;
75	  }
76	  decision.owner_id = lock->second;
77	  if (!IsTrafficBlockOwner(lock->second)) {
78	    decision.message = "route resource is reserved by mission: " + lock->second;
79	    return decision;
80	  }
81	  decision.success = true;
82	  decision.mutate_state = true;
83	  decision.message = "unblocked route " + from_station + " -> " + to_station;
84	  return decision;
85	}
86	
87	TrafficClearDecision PlanTrafficReservationClear(
88	    const std::string& resource_id, const RouteLockMap& route_locks) {
89	  TrafficClearDecision decision;
90	  decision.resource_id = resource_id;
91	  const auto lock = route_locks.find(resource_id);
92	  if (lock == route_locks.end()) {
93	    decision.message = "traffic reservation not found: " + resource_id;
94	    return decision;
95	  }
96	  decision.success = true;
97	  decision.owner_id = lock->second;
98	  if (IsTrafficBlockOwner(lock->second)) {
99	    decision.erase_resource = true;
100	    decision.message = "cleared blocked route " + resource_id;
101	    return decision;
102	  }
103	  decision.release_mission_id = lock->second;
104	  decision.message = "cleared mission route reservation " + resource_id;
105	  return decision;
106	}
107	
108	TrafficDeadlockDecision PlanTrafficDeadlockDetection(const RouteLockMap& route_locks) {
109	  TrafficDeadlockDecision decision;
110	  std::unordered_map<std::string, std::vector<std::string>> station_to_missions;
111	  std::unordered_map<std::string, std::vector<std::string>> station_to_resources;
112	  for (const auto& [resource_id, owner_id] : route_locks) {
113	    if (IsTrafficBlockOwner(owner_id)) {
114	      continue;
115	    }
116	    const auto lock = ParseRouteLock(resource_id);
117	    if (!lock.has_value()) {
118	      continue;
119	    }
120	    station_to_missions[lock->first].push_back(owner_id);
121	    station_to_missions[lock->second].push_back(owner_id);
122	    station_to_resources[lock->first].push_back(resource_id);
123	    station_to_resources[lock->second].push_back(resource_id);
124	  }
125	
126	  std::unordered_set<std::string> conflict_missions;
127	  std::unordered_set<std::string> conflict_resources;
128	  std::unordered_set<std::string> conflict_stations;
129	  for (const auto& [station_id, mission_ids] : station_to_missions) {
130	    std::unordered_set<std::string> unique_missions(mission_ids.begin(), mission_ids.end());
131	    if (unique_missions.size() < 2U) {
132	      continue;
133	    }
134	    conflict_stations.insert(station_id);
135	    std::vector<std::string> ordered_missions(unique_missions.begin(), unique_missions.end());
136	    std::sort(ordered_missions.begin(), ordered_missions.end());
137	    for (const auto& mission_id : ordered_missions) {
138	      conflict_missions.insert(mission_id);
139	    }
140	    const auto resource_it = station_to_resources.find(station_id);
141	    if (resource_it != station_to_resources.end()) {
142	      for (const auto& resource_id : resource_it->second) {
143	        conflict_resources.insert(resource_id);
144	      }
145	    }
146	    std::ostringstream desc;
147	    desc << "station " << station_id << " shared by missions ";
148	    for (std::size_t index = 0; index < ordered_missions.size(); ++index) {
149	      if (index > 0) {
150	        desc << ", ";
151	      }
152	      desc << ordered_missions[index];
153	    }
154	    decision.descriptions.push_back(desc.str());
155	  }
156	
157	  decision.deadlocked = !conflict_stations.empty();
158	  decision.mission_ids.assign(conflict_missions.begin(), conflict_missions.end());
159	  std::sort(decision.mission_ids.begin(), decision.mission_ids.end());
160	  decision.conflict_resource_ids.assign(conflict_resources.begin(), conflict_resources.end());
161	  std::sort(decision.conflict_resource_ids.begin(), decision.conflict_resource_ids.end());
162	  decision.conflict_station_ids.assign(conflict_stations.begin(), conflict_stations.end());
163	  std::sort(decision.conflict_station_ids.begin(), decision.conflict_station_ids.end());
164	  if (decision.deadlocked) {
165	    decision.message = "traffic deadlock candidates detected";
166	  }
167	  return decision;
168	}
169	
170	std::vector<std::string> BuildRouteLockIds(
171	    const std::vector<std::string>& station_path, const bool include_intersection_locks) {
172	  // A10：薄封装 —— 与 dispatcher::ResourceTable::BuildLockIds 同一实现
173	  return dispatcher::ResourceTable::BuildLockIds(station_path, include_intersection_locks);
174	}
175	
176	std::vector<std::string> PlanMissionRouteLocks(
177	    const amr_dispatcher_core::catalog::StationCatalog& catalog,
178	    const std::string& from_station, const std::string& to_station) {
179	  if (to_station.empty()) {
180	    // 目的站缺失：不预留任何锁，派发链随后按未知站点判负（保持现网行为）
181	    return {};
182	  }
183	  if (from_station.empty()) {
184	    // 无取货站（车辆当前位姿作起点）：只锁目的站节点，无法预知途经路段
185	    return {RouteNodeLockId(to_station)};
186	  }
187	  const auto path = amr_dispatcher_core::catalog::FindRoutePath(catalog, from_station, to_station);
188	  if (!path.has_value()) {
189	    // 目录断开/站点未知 -> 空锁集，照旧无锁派发
190	    return {};
191	  }
192	  return BuildRouteLockIds(*path, /*include_intersection_locks=*/true);
193	}
194	
195	bool ReserveRouteLocksForMission(
196	    RouteLockMap& route_locks, RouteLockReservationMap& route_locks_by_mission,
197	    const std::string& mission_id, const std::vector<std::string>& route_lock_ids,
198	    std::string* message) {
199	  for (const auto& lock_id : route_lock_ids) {
200	    const auto existing = route_locks.find(lock_id);
201	    if (existing != route_locks.end() && existing->second != mission_id) {
202	      if (message != nullptr) {
203	        *message = "route resource locked: " + lock_id + " by " + existing->second;
204	      }
205	      return false;
206	    }
207	  }
208	  for (const auto& lock_id : route_lock_ids) {
209	    route_locks[lock_id] = mission_id;
210	  }
211	  route_locks_by_mission[mission_id] = RouteLockReservation{mission_id, route_lock_ids};
212	  if (message != nullptr) {
213	    *message = "reserved " + std::to_string(route_lock_ids.size()) + " route lock(s)";
214	  }
215	  return true;
216	}
217	
218	bool ReleaseRouteLocksForMission(
219	    RouteLockMap& route_locks, RouteLockReservationMap& route_locks_by_mission,
220	    const std::string& mission_id) {
221	  bool released = false;
222	  const auto reservation = route_locks_by_mission.find(mission_id);
223	  if (reservation != route_locks_by_mission.end()) {
224	    for (const auto& lock_id : reservation->second.route_lock_ids) {
225	      const auto lock = route_locks.find(lock_id);
226	      if (lock != route_locks.end() && lock->second == mission_id) {
227	        route_locks.erase(lock);
228	        released = true;
229	      }
230	    }
231	    route_locks_by_mission.erase(reservation);
232	  }
233	  for (auto lock = route_locks.begin(); lock != route_locks.end();) {
234	    if (lock->second == mission_id) {
235	      lock = route_locks.erase(lock);
236	      released = true;
237	    } else {
238	      ++lock;
239	    }
240	  }
241	  return released;
242	}
243	
244	}  // namespace amr_dispatcher_core::workflow
