    RCLCPP_WARN(get_logger(),
                "Mission %s -> vehicle %s: BuildVda5050OrderFromPath failed "
                "(path %zu node(s)), VDA 5050 order NOT published",
                mission_id.c_str(), vehicle_id.c_str(), path_it->second.size());
    return;
